def test_postrepair_no_case_has_a_false_predicate():
    false_predicates = {
        c["case_id"]: [k for k, v in c["assertion_results"].items() if not v]
        for c in RESULT["cases"]
        if not all(c["assertion_results"].values())
    }
    assert false_predicates == {}
